-- OS::JOB — Préparation du schéma V1.
-- NE PAS exécuter pendant l'étape d'installation de l'interface.
-- Le schéma sera activé et expliqué lors du sprint base de données.
CREATE DATABASE IF NOT EXISTS os_job CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE os_job;
CREATE TABLE IF NOT EXISTS users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS search_spaces (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, name VARCHAR(160) NOT NULL, location_filter VARCHAR(255) NULL, salary_min INT UNSIGNED NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_spaces_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS job_offers (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, title VARCHAR(200) NOT NULL, company VARCHAR(190) NULL, city VARCHAR(160) NULL, salary_min INT UNSIGNED NULL, salary_max INT UNSIGNED NULL, source_url TEXT NULL, description LONGTEXT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_offers_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS search_offer_links (search_space_id BIGINT UNSIGNED NOT NULL, job_offer_id BIGINT UNSIGNED NOT NULL, PRIMARY KEY(search_space_id,job_offer_id), FOREIGN KEY(search_space_id) REFERENCES search_spaces(id) ON DELETE CASCADE, FOREIGN KEY(job_offer_id) REFERENCES job_offers(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS applications (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, job_offer_id BIGINT UNSIGNED NOT NULL, status VARCHAR(40) NOT NULL DEFAULT 'to_review', applied_at DATETIME NULL, notes TEXT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(job_offer_id) REFERENCES job_offers(id) ON DELETE CASCADE) ENGINE=InnoDB;
